import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"crypto — Overview","description":"","frontmatter":{},"headers":[],"relativePath":"std/crypto/index.md","filePath":"std/crypto/index.md"}`),a={name:`std/crypto/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="crypto-—-overview" tabindex="-1">crypto — Overview <a class="header-anchor" href="#crypto-—-overview" aria-label="Permalink to “crypto — Overview”">​</a></h1><p>A comprehensive, pure-Vex cryptographic suite. It has no OpenSSL or libsodium dependency. Application code should prefer the checked <code>Aes128Gcm</code>, <code>Aes256Gcm</code>, <code>ChaCha20Poly1305</code>, <code>HkdfSha256</code>, <code>Pbkdf2Sha256</code>, <code>Argon2id</code>, <code>X25519</code>, and <code>Ed25519</code> facades; raw <code>RawBuf</code> functions exist for protocol and runtime integration and require the caller to uphold buffer dimensions.</p><h2 id="module-map" tabindex="-1">Module Map <a class="header-anchor" href="#module-map" aria-label="Permalink to “Module Map”">​</a></h2><table tabindex="0"><thead><tr><th>Category</th><th>Algorithms</th><th>Files</th></tr></thead><tbody><tr><td><strong>Hashes</strong></td><td>SHA-1, SHA-256, SHA-512, BLAKE2b</td><td><code>sha1.vx</code>, <code>sha256.vx</code>, <code>sha512.vx</code>, <code>blake2b.vx</code></td></tr><tr><td><strong>MACs</strong></td><td>HMAC-SHA1, HMAC-SHA256</td><td><code>hmac.vx</code></td></tr><tr><td><strong>AEAD</strong></td><td>AES-GCM, ChaCha20-Poly1305</td><td><code>aes_gcm.vx</code>, <code>chacha20.vx</code>, <code>poly1305.vx</code>, <code>aead.vx</code></td></tr><tr><td><strong>Symmetric</strong></td><td>AES (128/256)</td><td><code>aes.vx</code></td></tr><tr><td><strong>KDF</strong></td><td>Argon2id, PBKDF2, HKDF</td><td><code>argon2id.vx</code>, <code>pbkdf2.vx</code>, <code>hkdf.vx</code></td></tr><tr><td><strong>Signatures</strong></td><td>Ed25519</td><td><code>ed25519.vx</code></td></tr><tr><td><strong>Key Exchange</strong></td><td>X25519 (ECDH)</td><td><code>x25519.vx</code></td></tr><tr><td><strong>Field Math</strong></td><td>Curve25519 field</td><td><code>field25519.vx</code></td></tr><tr><td><strong>Encoding</strong></td><td>Hex, Base64</td><td><code>hex.vx</code>, <code>base64.vx</code></td></tr><tr><td><strong>Utilities</strong></td><td>Byte ops, SIMD helpers</td><td><code>bytes.vx</code>, <code>simd.vx</code>, <code>utils.vx</code></td></tr></tbody></table><h2 id="design-principles" tabindex="-1">Design Principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to “Design Principles”">​</a></h2><ol><li><strong>Pure Vex</strong>: No C FFI calls — the compiler can inline and vectorize everything</li><li><strong>Hardware Acceleration</strong>: When <code>Crypto.*</code> builtins are available (AES-NI, ARMv8 CE), they are used transparently</li><li><strong>Software Fallbacks</strong>: Portable fixed-flow implementations preserve the same <code>Crypto.*</code> semantics when a target lacks a native instruction</li><li><strong>Failure safety</strong>: checked AEAD open operations release no unauthenticated plaintext and clear reusable output on failure</li><li><strong>Constant-flow primitives</strong>: tag comparison, AES portable fallback and polynomial multiplication avoid secret-dependent lookup tables and branches</li><li><strong>Target-width raw memory</strong>: every byte offset crossing a <code>RawBuf</code> boundary is a canonical <code>usize</code>. Algorithms may retain wider logical counters or block indices, but never narrow them implicitly while addressing memory.</li></ol><h2 id="raw-integration-boundary" tabindex="-1">Raw integration boundary <a class="header-anchor" href="#raw-integration-boundary" aria-label="Permalink to “Raw integration boundary”">​</a></h2><p>Checked facades are the application API. Raw functions exist for runtimes and protocol implementations that already own exact storage; their capacities and aliasing requirements are explicit caller obligations. They fail closed rather than truncate an unaddressable <code>u64</code> length. In particular, CTR requests are validated before their first output write, so a counter stream can never wrap and reuse keystream bytes. The initial-counter AES-CTR form permits its final <code>u32::MAX</code> block exactly once and rejects any request beyond that boundary.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};